// Strip quoted history and signatures before classification.
const m = $input.first().json;
const full = (m.text || m.snippet || '').toString();
const clean = full
  .split(/\n>|On .+wrote:|-----Original Message-----|_{5,}/)[0]
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 4000);
return [{ json: { method: 'POST', path: '/internal/replies', idempotencyKey: m.id, body: { workspaceId: $env.KLYRO_WORKSPACE_ID, enrollmentId: m.enrollmentId || null, threadId: m.threadId, contactEmail: (m.from || '').match(/[^<>\s]+@[^<>\s]+/)?.[0], replyText: clean, providerMessageId: m.id, subject: m.subject } } }];
